function validate([s1, s2]) {
  for (const s of [s1, s2]) {
    if (typeof s !== 'string' || s.length < 1 || s.length > 200) return 's1 and s2 each have 1 to 200 characters.';
    if (!/^[a-z]+( [a-z]+)*$/.test(s)) return 'Use lowercase words separated by single spaces, with no space at either end.';
  }
  return null;
}

