function uncommonFromSentences(s1, s2) {
  const count = new Map();
  const words = (s1 + ' ' + s2).split(' ');

  for (const word of words) {
    count.set(word, (count.get(word) || 0) + 1);
  }

  const result = [];
  for (const [word, freq] of count) {
    if (freq === 1) {
      result.push(word);
    }
  }
  return result;
}

