function uncommonFromSentences(s1, s2) {
  const a = s1.split(' '), b = s2.split(' ');
  const result = [];
  for (const w of a) if (a.filter(x => x === w).length === 1 && !b.includes(w)) result.push(w);
  for (const w of b) if (b.filter(x => x === w).length === 1 && !a.includes(w)) result.push(w);
  return result;
}

