function generate(rand, size) {
  const large = size === 'large';
  const vocabSize = large ? 30 + Math.floor(rand() * 30) : 2 + Math.floor(rand() * 5);
  const vocab = [];
  while (vocab.length < vocabSize) {
    const len = 1 + Math.floor(rand() * (large ? 6 : 3));
    let w = '';
    for (let i = 0; i < len; i++) w += String.fromCharCode(97 + Math.floor(rand() * (large ? 26 : 3)));
    if (!vocab.includes(w)) vocab.push(w);
  }
  const pick = () => vocab[Math.floor(rand() * vocab.length)];
  const sentence = () => {
    const limit = large ? 200 : 1 + Math.floor(rand() * 15);
    const words = [pick()];
    let length = words[0].length;
    for (;;) {
      if (!large && rand() < 0.2) break;
      const w = pick();
      if (length + 1 + w.length > limit) break;
      words.push(w);
      length += 1 + w.length;
    }
    return words.join(' ');
  };
  return [sentence(), sentence()];
}
